def transform(grid):
    # Remove a monochrome separator row or column and keep the section before it.
    if any(len(set(row)) == 1 for row in grid):
        sep = next(i for i,row in enumerate(grid) if len(set(row)) == 1)
        part = grid[:sep]
    else:
        sep = next(j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1)
        part = [row[:sep] for row in grid]
    return [[2 if x != 0 else 0 for x in row] for row in part]
print(transform(grid))
